// Adaptive midpoint integration with error control
double h = b - a;
double c = (a + b) / 2;
double one_step = h * f->eval(c);
double two_steps = (h / 2) * (f->eval(a + h / 4) + f->eval(b - h / 4));
double error = std::abs(one_step - two_steps) / 3;

if (error <= precision * std::abs(two_steps)) {
    return two_steps + (two_steps - one_step) / 3; // Richardson extrapolation
} else {
    return adaptive_midpoint(f, a, c, precision) + adaptive_midpoint(f, c, b, precision);
}

